#!/usr/bin/env python3
# THE DEUTERONOMY WALK 19b (LEAN): THE TAIL'S RECORDS in ONE call — the map's AS BUILT — LEAN (the template ch29b_asbuilt.txt filled from the prints: the departures, the
# lessons, the finds, the timing table), the state doc's tail NOTE under #230, the recovery page (section 2 rewritten under its cap), the memory (the index line and the walk
# note), the lean-pass box's line (11) in COMPILE_DEBT. Every number READ FROM ITS PRINT through ch29b_tail_facts.py; every text built whole before a file is opened; the lints
# asserted unmoved; the caps asserted. --check prints without writing. write_ch26b_records.py's form. RUN FROM THE REPO ROOT after the chain's SUMMARY is read (ALL GREEN).
import os, re, sys, subprocess
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ch29b_tail_facts import *
CHECK = '--check' in sys.argv
MAP = f'{ROOT}/World/step9/DEUTERONOMY_WALK.md'; SD = f'{ROOT}/logic/pre_logic_methods_2026-07-28/PROMPT_continue_solo_era_2026-08-06.md'; REC = f'{ROOT}/logic/pre_logic_methods_2026-07-28/RECOVERY_new_thread_2026-09-12.md'
DEBT = f'{ROOT}/World/step9/COMPILE_DEBT.md'; MM = f'{MEM}/MEMORY.md'; MW = f'{MEM}/deuteronomy-walk.md'
def sub1(t, a, b, name):
    assert t.count(a) == 1, (name, t.count(a), a[:70]); return t.replace(a, b)
print('THE PRINTS:', {k: (v if len(str(v)) < 90 else str(v)[:87] + '...') for k, v in D.items() if k != 'TABLE'})
ASB = rd(f'{SP}/ch29b_asbuilt.txt') % D
NOTE230 = (" — THE TAIL OF 19b (2026-09-27, after the machine's own compaction of RUN B's window — the cap passed; the rereads done; the owner's \"Stop everything now\" at the chain's second launch, his review of the cost, then \"Ok go\"): the chain's first SUMMARY read once — ONE STEP RED (the probes: %s — ten earlier probes moved by the marker's day (40, 11, 1) -> (40, 12, 7) and the reuses' counts and source lists; every other suite green; the long steps skipped; %d s); THE RETYPES FROM THE PRINT (patch_probes_retypes_ch29b.py by ast — %s elements over %s probes %s, the changed constant alone, a 19b comment line above each return; q20's nine-character cut of the last witness entry's source widened to ten — 31:28's head read 'Deut 31:2' at nine; the value from the one database's own print %s); the second pass launched and KILLED on the owner's word inside its probes — its print read: %s, Q47 alone: became_the_lords_people_this_day counted TWO inside the generator expression the walker leaves alone (patch_probe_q47_ch29b.py: %s); a second launch killed by me before its probes; the third pass FROM THE TAPE green through the register gate (the probe suites %s; the register gate --strict %s), KILLED BY THE SESSION'S MEMORY WATCHDOG at the positions step (four workers); the positions table outside the chain at two workers (%s) and the chain resumed --from checkpoint (the sweep %s; the journal unmoved) — ALL GREEN over the two pieces in %d s (%d steps) — no further demand; the four records and the debt line (11) written in one call (write_ch29b_records.py; the map's AS BUILT from the template ch29b_asbuilt.txt with the departures 1-16 and the lessons 1-20), the forms copied, the commit message at <scratch>/commit_msg_ch29b.txt (18b + 19 + 19b folded; the trailers once); the tree UNCOMMITTED since 68191ea. THE COST FINDINGS (the owner's review, 2026-09-27): RUN B's window ran past the 600k cap to the machine's own compaction; the cache law broken about twenty times (waits of 3-9 minutes at 300-600k — every check imports the 76 runners); the tail begun without his word; a marker sitting splits its RUN B and runs the readback suite before the chain. NEXT ON HIS WORD: the commit (\"Commit\" = no push; \"commit push\" = both — 18b + 19 + 19b); then, after a compaction (\"Reread\", then \"Go\"), SITTING 20 — THE READING OF CHAPTER 32 (the song), LEAN, two runs + the tail. POST-COMPACTION REREADS: the recovery page, the map's newest section (\"Sitting 19b — THE COMPILE OF CHAPTERS 29-31 — AS BUILT — LEAN\"), MEMORY.md; then this checkpoint."
           % (RB1, CHAIN1, NRET, NRETP, RETQ, HW, RBK, Q47FIX, D['PROBES'], REG, POS, SWEEP, CHAIN_S, len(STEPS)))
DEBT_LINE = (" (11) sitting 19b (2026-09-27) — CHAPTERS 29-31 COMPILED, LEAN, ONE RUNNER OVER THREE UNITS AND A NARRATIVE CHAPTER (two runs + the tail; RUN A in the reading's tail window, RUN B to the machine's compaction — the cap broken): the seven rows the ledger cites, read whole at the design (%s); NO docket, NO Talmud folio read; fifteen cells and the table, %d cases %s; twenty lines in three forms (13 statute, 4 act, 3 speech), %d writes (fifty-nine new, nine reuse seats), %s parameters (the hakhel's time and Moses' death date in the registry); THE ONE MARKER at 31:1 for 31:2's number — Moses' last day (40, 12, 7): the year the ink's, the month and the day the answer sheet's (Tosefta Sotah 11:3; Seder Olam 10:2 and Kiddushin 38a on the kin), the counter moved for the first time in the book, six timers fired on the walk; %d edges from the runner (thirty-three CALL reference; four token edges FALSE by homograph — the sabbath, the harlot, the talion's 'under', Molech; the registration edge); the pointers 29:12, 31:3, 31:4 RUN_CITATION and 30:9 FALSE; the pointer row 31:10 (the hakhel — 15b's OWED) PAID grade R; the false six at 30:9 GUARDED by CALL; the tape %s on its third run; the chain's first pass ten readback probes RED (the marker's day and the reuses — %s elements retyped from the print, one more inside a generator expression), ALL GREEN on its second pass from the tape (sweep %s); OWED: the docket whole (Sotah 7 — 41a-b; Berakhot 9; Avot 1; Chagigah 1 and 3a; Bava Batra 14a-15a; Bava Metzia 59b; Sanhedrin 43b and 90b; Temurah 16a; Eruvin 54b-55a; Megillah 31b; Rosh Hashanah 8b and 12b; Arakhin 28b; Tosefta Sotah 11 whole and Ketubot 5; the Jerusalem Talmud Sotah 7:7), the readback's exercise of the hakhel, the charge and the return on the Prophets' and the Writings' tapes, THE THREE GIFTS' DAEMON (34:5), the song's own lines (32:1-43 at sitting 20), the persons and the bench scene, the pointer rows for the Prophets' and the Writings' seats (1 Kings 9:8, Jeremiah 22:8, Nehemiah 1:9, Joshua 1:5-9, 4:19, 5:12, 8:34, Micah 7:5, Zechariah 11:8, Malachi 2:6, Psalms 47:10 against Numbers 21:18), the rest of the three chapters' glosses, the ink forms' own lint flags (ch22_ink.py, ch26_ink.py, ch29_ink.py's copy to measure), sitting 15's two manifests' middah strings, THE INSTALL HYPOTHESIS, the ten deferred records, the full process; the commit on his word. 20 (the reading of 32): next."
             % (EXAMROWS, CASES, MATRIX, NWRITES, PAR, MINE, VS[-1], NRET, SWEEP))
# ---- the texts checked against the files ----
m = rd(MAP); assert '## Sitting 19b — THE COMPILE OF CHAPTERS 29-31 — AS BUILT' not in m and m.rfind('## Sitting 19b — THE COMPILE OF CHAPTERS 29-31, Deuteronomy 29:1-31:30 — LEAN') > 0 and m.find('\n## ', m.rfind('## Sitting 19b — THE COMPILE OF CHAPTERS 29-31, Deuteronomy') + 10) < 0
sd = rd(SD); assert '\n#230 (' in sd and 'THE TAIL OF 19b (' not in sd
i230 = sd.index('\n#230 ('); assert sd.find('\n#2', i230 + 5) < 0, 'the #230 the last checkpoint'
rec = rd(REC); i, j = rec.index('## 2. WHERE IT STANDS'), rec.index('## 3. THE STANDING LAWS'); assert 0 < i < j
SEC2 = ('## 2. WHERE IT STANDS (2026-09-27; #230 — sitting 19b DONE, newest)\n'
        '- NUMBERS CLOSED. DEUTERONOMY 1:1-31:30 ON THE TAPE (1-25 PUSHED through 68191ea; 26-31 uncommitted).\n'
        '- units 247 / standing 2344, hash 8b8fff1fa28953af. %s runners, %s daemons; %s kinds / %s effects.\n'
        '- THE TAPE at RUN (%s, pairs, 127); %s on its %d runs; MARKERS 173 — Moses\' last day (40, 12, 7) at 31:1; checkpoint_check %s.\n'
        '- ⚠ THE LEAN PASS (#208): 16-34 in 8 lean sittings — core shelf, 4 records, chain once; full process OWED.\n'
        '- 18b + 19 + 19b UNCOMMITTED since 68191ea; message <scratch>/commit_msg_ch29b.txt.\n'
        '- SITTING 19b (ch 29-31 COMPILE, LEAN) DONE at #230: runner covenant_return_charge %s; %d edges; chain: ten readback probes RED once (the marker\'s day, the reuses; retyped from the print), then ALL GREEN (sweep %s); THE CAP BROKEN in RUN B: a marker sitting splits RUN B. NEXT: commit on his word; then 20 (ch 32, lean).\n\n\n'
        % (DGL, DAEM, KREG, EREG, RUN, VS[-1], len(TAPES), CC, MATRIX, MINE, SWEEP))
rec2 = rec[:i] + SEC2 + rec[j:]; rec2 = sub1(rec2, 'cold_run_<span>.py (75 runners', 'cold_run_<span>.py (76 runners', 'the file map')
mm = rd(MM)
g = re.search(r"19b \(the compile of 29-31, LEAN\) RUN A \+ RUN B 2026-09-27 at #230 \(.*?\); NEXT: THE TAIL \(.*?\), then the commit on his word \(18b \+ 19 \+ 19b\)", mm); assert g, 'the walk line'
NEWL = "19b DONE 2026-09-27 at #230 (the compile — the 76th runner covenant_return_charge %s in six parts + the generated cases; %s kinds in three forms / %s effects + %s seats; ONE MARKER at 31:1 — Moses' last day (40, 12, 7), markers 173; the tape %s on its third run; %d edges; the chain: ten readback probes RED on its first pass (the marker's day, the reuses — retyped from the print), ALL GREEN on its second pass from the tape; THE CAP BROKEN in RUN B's window — a marker sitting splits RUN B and runs the readback suite before the chain), UNCOMMITTED since 68191ea; NEXT: the commit on his word (18b + 19 + 19b), then 20 (the reading of 32, lean) after a compaction" % (MATRIX, KADD, EADD, SEATS, VS[-1], MINE)
mm2 = mm[:g.start()] + NEWL + mm[g.end():]
mw = rd(MW)
mw2 = sub1(mw, 'description: "SITTING 19b RUN B AT ITS CLEAN POINT 2026-09-27 (chapters 29-31 COMPILED lean — the 76th runner covenant_return_charge %s, %s kinds in three forms / %s effects, ONE MARKER at 31:1 Moses\' last day, the tape %s, %d edges, the chain LAUNCHED; NEXT THE TAIL then the commit on his word) — ' % (MATRIX, KADD, EADD, VS[-1], MINE),
           'description: "SITTING 19b DONE 2026-09-27 (chapters 29-31 COMPILED lean — the 76th runner covenant_return_charge %s, %s kinds in three forms / %s effects, ONE MARKER at 31:1 Moses\' last day, the tape %s on its third run, %d edges, the chain ALL GREEN on its second pass; THE CAP BROKEN in RUN B; UNCOMMITTED; NEXT the commit on his word, then 20 from 32:1) — ' % (MATRIX, KADD, EADD, VS[-1], MINE), 'the description')
mw2 = mw2.rstrip('\n') + ("\n\nSITTING 19b DONE 2026-09-27 (the tail, after the machine's own compaction of RUN B's window; the owner's \"Stop everything now\" at the chain's second launch, his review, then \"Ok go\"): the gates chain's first pass ONE STEP RED (%d s — the readback suite %s: ten earlier probes moved by the marker's day and the reuses), the retypes from the print (%s elements over %s probes by ast; q20's nine-character cut widened to ten; Q47's one element inside a generator expression found by the killed pass's print — %s), the second pass from the tape ALL GREEN in two pieces (%d steps, %d s — the probe suites all full, the register gate strict %s; killed by the memory watchdog at the positions step, the positions at two workers outside the chain %s, then --from checkpoint: the sweep %s, the journal unmoved); the records written (the map's AS BUILT from a template filled from the prints — the departures 1-16, the lessons 1-20), the forms copied, the message built (18b + 19 + 19b). THE LESSONS BEYOND RUN B'S SEVEN: a marker sitting is bigger than a statute sitting — its RUN B splits into two windows (RUN B ran to the machine's compaction, the 600k cap broken); the marker moves the probes that ASSERT THE COUNTER'S DAY as well as those counting the markers, and the readback suite runs right after the tape's 10/10, before the chain; a marker's walk fires the timers due in it; a later reuse moves earlier runners' literals (an entity list, a KIN_EXPECTED count); the gate's live edge is `alias.name(` and a comment carrying the form satisfies it falsely; a probe's own cut ends before the answer; the one database holds every tape run's writes; an element inside a generator expression hides from the ast walker; THE CACHE LAW WAS BROKEN about twenty times by 3-9 minute checks at a big context — one background wrapper per phase with its readers written first; THE TAIL OPENS ON HIS WORD, the harness's continuation is not it; the positions table at four workers is killed by the memory watchdog when other sessions share the machine (two workers outside the chain, then --from checkpoint). %d timed steps, %d machine seconds. UNCOMMITTED since 68191ea. NEXT on his word: the commit; then 20 (the reading of 32, the song, lean) after a compaction.\n"
                          % (CHAIN1, RB1, NRET, NRETP, Q47FIX, len(STEPS), CHAIN_S, REG, POS, SWEEP, NSTEP, TSEC))
debt = rd(DEBT); anchor = ' 19b (the compile of 29-31): next.'; assert debt.count(anchor) == 1, debt.count(anchor); debt2 = debt.replace(anchor, DEBT_LINE)
for t in (ASB, NOTE230, DEBT_LINE, mw2[len(mw):], SEC2, NEWL): assert not re.search(r'[֐-׿]', t), 'no Hebrew script in the new texts'
for t in (ASB, NOTE230, DEBT_LINE, mw2, rec2, mm2): assert os.path.expanduser('~') not in t and SP not in t, 'a home or scratch path'
assert len(rec2.encode()) <= 10240 and len(mm2.encode()) < 17000, (len(rec2.encode()), len(mm2.encode()))
LINT = {}
for p in (MAP, SD, REC, MM, MW, DEBT):
    r = subprocess.run(['python3', f'{ROOT}/logic/solo_tools/gloss_lint.py', p], capture_output=True, text=True); LINT[os.path.basename(p)] = int(re.search(r'(\d+) flag', r.stdout).group(1))
print('THE RECORDS %s: the AS BUILT %d bytes; the NOTE %d; the recovery page %d; MEMORY.md %d; the walk note %d; the debt line %d; the lints before %s' % ('CHECKED' if CHECK else 'WRITTEN', len(ASB.encode()), len(NOTE230.encode()), len(rec2.encode()), len(mm2.encode()), len(mw2.encode()), len(DEBT_LINE.encode()), LINT))
if not CHECK:
    open(MAP, 'w', encoding='utf-8').write(m.rstrip('\n') + ASB)
    open(SD, 'w', encoding='utf-8').write(sd.rstrip('\n') + NOTE230 + '\n')
    open(REC, 'w', encoding='utf-8').write(rec2); open(MM, 'w', encoding='utf-8').write(mm2); open(MW, 'w', encoding='utf-8').write(mw2); open(DEBT, 'w', encoding='utf-8').write(debt2)
    L2 = {}
    for p in (MAP, SD, REC, MM, MW, DEBT):
        r = subprocess.run(['python3', f'{ROOT}/logic/solo_tools/gloss_lint.py', p], capture_output=True, text=True); L2[os.path.basename(p)] = int(re.search(r'(\d+) flag', r.stdout).group(1))
    assert L2 == LINT, (LINT, L2)
    print('THE RECORDS WRITTEN — every lint unmoved:', L2)
